import { Badge } from '@/components/ui/Badge';
import { siteConfig } from '@/config/site.config';
import { useLanguage } from '@/components/layout/LanguageProvider';
import type { EnrichedTerm } from '@/types/knowledge.types';

interface Props {
  term: EnrichedTerm;
  onClick: () => void;
}

export function TermCard({ term, onClick }: Props) {
  const { lang, t } = useLanguage();
  const color =
    (siteConfig.theme.colors.categories as Record<string, string>)[term.category] ||
    siteConfig.theme.colors.primary;

  const primaryName = lang === 'ar' ? term.term_ar : term.term_en;
  const secondaryName = lang === 'ar' ? term.term_en : term.term_ar;

  return (
    <button
      onClick={onClick}
      className="group w-full rounded-xl border border-border bg-surface p-4 text-start transition-all hover:border-primary/50 hover:bg-surface-elevated hover:shadow-[0_0_20px_rgba(139,92,246,0.15)]"
    >
      <div className="mb-2 flex items-center justify-between">
        <Badge color={color}>{t(`categories.${term.category}`)}</Badge>
        <span className="text-xs text-text-muted">#{term.id}</span>
      </div>
      <h3 className="mb-0.5 font-bold text-text-primary group-hover:text-primary">
        {primaryName}
      </h3>
      <p className="text-xs text-text-muted" dir={lang === 'ar' ? 'ltr' : 'rtl'}>
        {secondaryName}
      </p>
    </button>
  );
}