import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { siteConfig } from '@/config/site.config';
import { useWizardStore } from '@/lib/store/wizardStore';
import { useLanguage } from '@/components/layout/LanguageProvider';
import { getRawTermMap, loadEnglishExamples, getEnglishExampleSync } from '@/lib/utils/dataLoader';
import type { EnrichedTerm, RawTerm } from '@/types/knowledge.types';

interface Props {
  term: EnrichedTerm | null;
  onClose: () => void;
}

export function TermDetail({ term, onClose }: Props) {
  const navigate = useNavigate();
  const { setAnswers } = useWizardStore();
  const { lang, t } = useLanguage();
  const [raw, setRaw] = useState<RawTerm | null>(null);
  const [examplesEnReady, setExamplesEnReady] = useState(false);

  // Load raw Arabic explanation + English examples once
  useEffect(() => {
    getRawTermMap()
      .then((map) => {
        if (term) setRaw(map.get(term.id) || null);
        else setRaw(null);
      })
      .catch(() => setRaw(null));
  }, [term?.id]);

  useEffect(() => {
    loadEnglishExamples()
      .then(() => setExamplesEnReady(true))
      .catch(() => setExamplesEnReady(true));
  }, []);

  if (!term) return null;

  const color =
    (siteConfig.theme.colors.categories as Record<string, string>)[term.category] ||
    siteConfig.theme.colors.primary;

  const primaryName = lang === 'ar' ? term.term_ar : term.term_en;
  const secondaryName = lang === 'ar' ? term.term_en : term.term_ar;

  // Explanation: Arabic from knowledge-base, English from prompt_summary (which is English)
  const explanation =
    lang === 'ar' && raw?.detailed_explanation
      ? raw.detailed_explanation
      : term.prompt_summary;

  // Examples: language-aware
  // - Arabic: prefer raw.examples (Arabic), else fallback to prompt_example
  // - English: prefer English file, else fallback to prompt_example
  const examples: string[] =
    lang === 'en'
      ? [
          (examplesEnReady ? getEnglishExampleSync(term.id) : undefined) ||
            term.prompt_example,
        ]
      : raw?.examples?.length
        ? raw.examples
        : [term.prompt_example];

  const handleUseInPrompt = () => {
    setAnswers({ mode: 'learn-skill', skillTermId: term.id });
    onClose();
    navigate('/create/learn-skill');
  };

  const handleAddToCustom = () => {
    setAnswers({ mode: 'custom', customTermIds: [term.id] });
    onClose();
    navigate('/custom');
  };

  return (
    <Modal open={!!term} onClose={onClose} title={primaryName} size="lg">
      <div className="space-y-4">
        <div className="flex flex-wrap items-center gap-2">
          <Badge color={color}>{term.category}</Badge>
          <Badge>{term.complexity}</Badge>
          <span className="text-xs text-text-muted">#{term.id}</span>
        </div>

        <p
          className="text-sm font-bold text-text-muted"
          dir={lang === 'ar' ? 'ltr' : 'rtl'}
        >
          {secondaryName}
        </p>

        <div>
          <h4 className="mb-1 text-sm font-bold text-primary">
            {t('explorer.detail.explanation')}
          </h4>
          <p className="text-sm leading-relaxed text-text-secondary" dir="auto">
            {explanation}
          </p>
        </div>

        <div>
          <h4 className="mb-1 text-sm font-bold text-primary">
            {t('explorer.detail.examples')}
          </h4>
          <div className="space-y-2">
            {examples.slice(0, 3).map((ex, i) => (
              <p
                key={i}
                className="rounded-lg border border-border bg-bg p-3 text-sm text-text-secondary"
                dir="auto"
              >
                {ex}
              </p>
            ))}
          </div>
        </div>

        {term.related_terms.length > 0 && (
          <div>
            <h4 className="mb-1 text-sm font-bold text-primary">
              {t('explorer.detail.relatedTerms')}
            </h4>
            <div className="flex flex-wrap gap-1">
              {term.related_terms.map((id) => (
                <span
                  key={id}
                  className="rounded-md bg-surface-elevated px-2 py-1 text-xs text-text-secondary"
                >
                  #{id}
                </span>
              ))}
            </div>
          </div>
        )}

        <div className="flex flex-wrap gap-2 border-t border-border pt-4">
          <Button onClick={handleUseInPrompt}>
            {t('explorer.detail.teachMe')}
          </Button>
          <Button variant="secondary" onClick={handleAddToCustom}>
            {t('explorer.detail.addToCustom')}
          </Button>
        </div>
      </div>
    </Modal>
  );
}