import { cn } from '@/lib/utils/cn';
import { siteConfig } from '@/config/site.config';
import { useLanguage } from '@/components/layout/LanguageProvider';

interface Props {
  value: string;
  onChange: (v: string) => void;
  counts: Record<string, number>;
}

const CATEGORIES = [
  'all',
  'writing-hacks',
  'storytelling',
  'camera-presence',
  'hooks',
  'cta',
  'editing',
] as const;

export function CategoryTabs({ value, onChange, counts }: Props) {
  const { t } = useLanguage();
  return (
    <div className="flex flex-wrap gap-2">
      {CATEGORIES.map((id) => {
        const active = value === id;
        const color =
          id === 'all'
            ? siteConfig.theme.colors.primary
            : siteConfig.theme.colors.categories[id];
        const count = id === 'all' ? Object.values(counts).reduce((s, n) => s + n, 0) : counts[id] || 0;
        return (
          <button
            key={id}
            onClick={() => onChange(id)}
            className={cn(
              'rounded-lg border px-3 py-1.5 text-xs font-bold transition-all',
              active
                ? 'border-transparent text-white'
                : 'border-border bg-surface text-text-secondary hover:border-primary/50',
            )}
            style={active ? { backgroundColor: color } : undefined}
          >
            {id === 'all' ? t('common.all') : t(`categories.${id}`)} ({count})
          </button>
        );
      })}
    </div>
  );
}