import { useEffect, useMemo, useState } from 'react';
import { SearchBar } from '@/components/explorer/SearchBar';
import { CategoryTabs } from '@/components/explorer/CategoryTabs';
import { TermCard } from '@/components/explorer/TermCard';
import { TermDetail } from '@/components/explorer/TermDetail';
import { loadTermMetadata } from '@/lib/utils/dataLoader';
import { useLanguage } from '@/components/layout/LanguageProvider';
import type { EnrichedTerm } from '@/types/knowledge.types';

export default function ExplorerPage() {
  const { t } = useLanguage();
  const [terms, setTerms] = useState<EnrichedTerm[]>([]);
  const [q, setQ] = useState('');
  const [cat, setCat] = useState('all');
  const [active, setActive] = useState<EnrichedTerm | null>(null);

  useEffect(() => {
    loadTermMetadata().then((m) => setTerms(m.terms as EnrichedTerm[]));
  }, []);

  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const t of terms) c[t.category] = (c[t.category] || 0) + 1;
    return c;
  }, [terms]);

  const filtered = useMemo(() => {
    return terms.filter((t) => {
      const matchCat = cat === 'all' || t.category === cat;
      const matchQ =
        !q ||
        t.term_ar.includes(q) ||
        t.term_en.toLowerCase().includes(q.toLowerCase()) ||
        t.prompt_summary.toLowerCase().includes(q.toLowerCase());
      return matchCat && matchQ;
    });
  }, [terms, cat, q]);

  return (
    <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6">
      <div className="mb-6">
        <h1 className="mb-1 text-3xl font-bold text-gradient">{t('explorer.title')}</h1>
        <p className="text-sm text-text-secondary">{t('explorer.subtitle', { count: terms.length })}</p>
      </div>

      <div className="mb-4">
        <SearchBar value={q} onChange={setQ} placeholder={t('explorer.searchPlaceholder')} />
      </div>

      <div className="mb-6">
        <CategoryTabs value={cat} onChange={setCat} counts={counts} />
      </div>

      {filtered.length === 0 ? (
        <div className="rounded-xl border border-border bg-surface p-12 text-center text-text-muted">
          {t('explorer.noResults')}
        </div>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {filtered.map((t) => (
            <TermCard key={t.id} term={t} onClick={() => setActive(t)} />
          ))}
        </div>
      )}

      <TermDetail term={active} onClose={() => setActive(null)} />
    </div>
  );
}